import json
import uvicorn
from vonk_control.api import production_app
app = production_app()
allowed = {
 "recipe run observation time must be timezone-aware",
 "recipe run observation time is outside the accepted window",
 "recipe run observation is not assigned",
 "recipe run observation node is unavailable",
 "recipe run observation receipt key is stale",
 "recipe run observation generation is stale",
 "recipe run observation was replayed",
}
def wrap(handler):
 async def diagnostic(request, error):
  if request.url.path.endswith("/recipe-runs/observations"):
   detail = getattr(error, "detail", None)
   record = {"error_type": type(error).__name__, "status": getattr(error, "status_code", None), "reason": detail if isinstance(detail, str) and detail in allowed else "unclassified"}
   if hasattr(error, "errors"):
    record["validation"] = [{"type": e["type"], "loc": list(e["loc"])} for e in error.errors()][:8]
   print("EVALUATION_OBSERVATION_REJECTION " + json.dumps(record), flush=True)
  return await handler(request, error)
 return diagnostic
for kind, handler in list(app.exception_handlers.items()):
 app.add_exception_handler(kind, wrap(handler))
uvicorn.run(app, host="0.0.0.0", port=8000, access_log=False)
